 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    tiles = []
    # Motifs: 2x2 square, and the three observed L triomino orientations.
    shapes = [
        ([(0,0),(0,1),(1,0),(1,1)], 1),
        ([(0,0),(0,1),(1,1)], 3),
        ([(0,1),(1,0),(1,1)], 2),
        ([(0,0),(1,0),(1,1)], 4),
    ]
    for shape, color in shapes:
        mh = max(r for r,c in shape)+1
        mw = max(c for r,c in shape)+1
        for r in range(h-mh+1):
            for c in range(w-mw+1):
                ps = frozenset((r+dr,c+dc) for dr,dc in shape)
                if ps <= cells:
                    tiles.append((ps,color))
    by_cell = {p: [] for p in cells}
    for tile in tiles:
        for p in tile[0]: by_cell[p].append(tile)
    best = None
    def search(rem, chosen):
        nonlocal best
        if not rem:
            best = chosen[:]
            return True
        p = min(rem, key=lambda q: sum(t[0] <= rem for t in by_cell[q]))
        # Prefer larger tiles, then deterministic coordinate order.
        for ps,color in sorted(by_cell[p], key=lambda t: -len(t[0])):
            if ps <= rem and search(rem-ps, chosen+[(ps,color)]):
                return True
        return False
    search(frozenset(cells), [])
    out = [[0]*w for _ in range(h)]
    if best is None:
        return out
    for ps,color in best:
        for r,c in ps: out[r][c] = color
    return out

